const forecast = $('Get Forecast').first().json?.properties?.periods || [];
const calData = $('Get Calendar').first().json || {};
const newsRaw = $('Get News').first().json || '';

// Weather
const today = forecast[0] || {};
const tonight = forecast[1] || {};

// Calendar
const now = new Date();
const todayStr = now.toDateString();
const events = (calData.events || []).filter(e => {
  const d = new Date(e.date || e.start);
  return d.toDateString() === todayStr;
});
const tasks = (calData.tasks || []).filter(t => t.status !== 'done');
const meds = calData.meds || [];

// News (basic RSS parsing)
const newsText = typeof newsRaw === 'string' ? newsRaw : JSON.stringify(newsRaw);
const titles = (newsText.match(/<title>([^<]+)<\/title>/g) || []).slice(1, 6).map(t => t.replace(/<\/?title>/g, ''));

// Time greeting
const hour = now.getHours();
let greeting = 'Good morning';
if (hour >= 12 && hour < 17) greeting = 'Good afternoon';
else if (hour >= 17) greeting = 'Good evening';

const dateStr = now.toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric' });

const briefing = [
  `${greeting}! Here's your briefing for ${dateStr}:`,
  '',
  `WEATHER: ${today.shortForecast || 'Unavailable'}, ${today.temperature || '?'}°${today.temperatureUnit || 'F'}. Tonight: ${tonight.shortForecast || '?'}, ${tonight.temperature || '?'}°.`,
  '',
  `TODAY'S EVENTS (${events.length}):`,
  events.length ? events.map(e => `  - ${e.time || ''} ${e.title || e.name}`).join('\n') : '  No events today.',
  '',
  `PENDING TASKS (${tasks.length}):`,
  tasks.length ? tasks.slice(0, 5).map(t => `  - ${t.title || t.name} (due: ${t.due || 'no date'})`).join('\n') : '  All caught up!',
  '',
  `MEDICATIONS:`,
  meds.length ? meds.map(m => `  - ${m.name}: ${m.dose} (${m.frequency})`).join('\n') : '  None tracked.',
  '',
  `TOP HEADLINES:`,
  titles.length ? titles.map((t, i) => `  ${i+1}. ${t}`).join('\n') : '  No news available.'
].join('\n');

return {
  json: {
    greeting: greeting,
    date: dateStr,
    briefing_text: briefing,
    weather: {
      forecast: today.shortForecast,
      temperature: today.temperature,
      unit: today.temperatureUnit,
      tonight: tonight.shortForecast
    },
    calendar: {
      events_today: events.length,
      pending_tasks: tasks.length,
      events: events,
      tasks: tasks.slice(0, 5)
    },
    meds: meds,
    news: titles,
    generated_at: now.toISOString()
  }
};
